<?php
declare(strict_types=1);
require __DIR__.'/bootstrap.php';

$pdo=cc_db();
if(!$pdo){http_response_code(503);exit('Surf Match beta is temporarily unavailable.');}
$locations=$pdo->query("SELECT slug,name,region,lat,lon,timezone FROM locations WHERE active=1 ORDER BY sort_order,id")->fetchAll();
$raw=[];
foreach($pdo->query("SELECT cache_key,payload,updated_at FROM forecast_cache WHERE cache_key LIKE 'weather:%' OR cache_key LIKE 'marine:%'")->fetchAll() as $r){
  $j=json_decode((string)$r['payload'],true);if(is_array($j))$raw[(string)$r['cache_key']]=['data'=>$j,'updated_at'=>(string)$r['updated_at']];
}
function cc_beta_compass(?float $deg): string {if($deg===null)return '—';$p=['N','NE','E','SE','S','SW','W','NW'];return $p[(int)round(fmod($deg+360,360)/45)%8];}
function cc_beta_val(array $a,string $k,int $i): ?float {return isset($a[$k][$i])&&is_numeric($a[$k][$i])?(float)$a[$k][$i]:null;}
function cc_beta_day_index(array $daily,string $date): ?int {$times=$daily['time']??[];$i=array_search($date,$times,true);return $i===false?null:(int)$i;}
function cc_beta_uv_est(float $uvMax,int $epoch,int $sunrise,int $sunset): float {if($uvMax<=0||$epoch<=$sunrise||$epoch>=$sunset)return 0.0;$x=($epoch-$sunrise)/max(1,$sunset-$sunrise);$shape=pow(max(0.0,sin(M_PI*$x)),1.35);return round($uvMax*$shape,1);}

$right=['burleigh','currumbin','kirra','greenmount','snapper-rocks','the-pass','wategos'];
$point=['burleigh','currumbin','kirra','greenmount','snapper-rocks','the-pass','wategos'];
$river=['the-spit','tweed-river','brunswick-heads'];
$spots=[];
foreach($locations as $loc){
  $slug=(string)$loc['slug'];$w=$raw['weather:'.$slug]['data']??null;$m=$raw['marine:'.$slug]['data']??null;
  if(!is_array($w)||!is_array($m))continue;
  $tzName=(string)($loc['timezone']?:'Australia/Brisbane');try{$tz=new DateTimeZone($tzName);}catch(Throwable $e){$tz=new DateTimeZone('Australia/Brisbane');}
  $weatherHourly=$w['hourly']??[];$marineHourly=$m['hourly']??[];$wtimes=$weatherHourly['time']??[];$mtimes=$marineHourly['time']??[];$wIndex=[];foreach($wtimes as $i=>$t)$wIndex[(string)$t]=(int)$i;
  $hours=[];
  foreach($mtimes as $mi=>$t){
    $wi=$wIndex[(string)$t]??null;if($wi===null)continue;
    try{$dt=new DateTimeImmutable((string)$t,$tz);}catch(Throwable $e){continue;}
    $date=$dt->format('Y-m-d');$di=cc_beta_day_index($w['daily']??[],$date);
    $uvMax=($di!==null&&isset($w['daily']['uv_index_max'][$di])&&is_numeric($w['daily']['uv_index_max'][$di]))?(float)$w['daily']['uv_index_max'][$di]:0.0;
    $sunrise=null;$sunset=null;if($di!==null){try{$sunrise=new DateTimeImmutable((string)($w['daily']['sunrise'][$di]??''),$tz);$sunset=new DateTimeImmutable((string)($w['daily']['sunset'][$di]??''),$tz);}catch(Throwable $e){$sunrise=$sunset=null;}}
    $uv=($sunrise&&$sunset)?cc_beta_uv_est($uvMax,$dt->getTimestamp(),$sunrise->getTimestamp(),$sunset->getTimestamp()):0.0;
    $wh=cc_beta_val($marineHourly,'wave_height',$mi);$wp=cc_beta_val($marineHourly,'wave_period',$mi);$sh=cc_beta_val($marineHourly,'swell_wave_height',$mi);$sp=cc_beta_val($marineHourly,'swell_wave_period',$mi);$sd=cc_beta_val($marineHourly,'swell_wave_direction',$mi);$wd=cc_beta_val($weatherHourly,'wind_direction_10m',$wi);$ws=cc_beta_val($weatherHourly,'wind_speed_10m',$wi);$rain=cc_beta_val($weatherHourly,'precipitation_probability',$wi);
    $power=($wh!==null&&$wp!==null)?round(0.49*$wh*$wh*$wp,2):null;
    $hours[]=['epoch'=>$dt->getTimestamp(),'local'=>$dt->format('D j M, g:i a'),'date'=>$date,'hour'=>(int)$dt->format('G'),'wave_height'=>$wh,'wave_period'=>$wp,'swell_height'=>$sh,'swell_period'=>$sp,'swell_direction'=>$sd,'swell_compass'=>cc_beta_compass($sd),'wind_speed'=>$ws,'wind_direction'=>$wd,'wind_compass'=>cc_beta_compass($wd),'rain_probability'=>$rain,'uv'=>$uv,'uv_max'=>$uvMax];
  }
  $spots[]=['slug'=>$slug,'name'=>(string)$loc['name'],'region'=>(string)$loc['region'],'lat'=>(float)$loc['lat'],'lon'=>(float)$loc['lon'],'timezone'=>$tzName,'handedness'=>in_array($slug,$right,true)?'right':'both','break_type'=>in_array($slug,$point,true)?'point':(in_array($slug,$river,true)?'river':'beach'),'offshore_from'=>in_array((string)$loc['region'],['Gold Coast','Tweed Coast'],true)?275:260,'hours'=>$hours];
}
$dataset=json_encode($spots,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE|JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT)?:'[]';
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Surf Match Beta | CostaCams</title>
<style>
:root{--bg:#050606;--panel:#0d1011;--panel2:#121719;--line:#273035;--text:#eef4f5;--muted:#93a1a6;--aqua:#50dcff;--green:#69e0a0;--amber:#ffbf69;--red:#ff7468}*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 50% -20%,#12303a 0,#07090a 35%,#050606 72%);color:var(--text);font:14px/1.45 system-ui,-apple-system,Segoe UI,sans-serif}.top{display:flex;justify-content:space-between;align-items:center;padding:14px max(16px,3vw);border-bottom:1px solid #1f282b;background:#050606e8;position:sticky;top:0;z-index:30;backdrop-filter:blur(12px)}.brand{font-weight:900;letter-spacing:.1em}.brand b{color:var(--aqua)}.beta{font-size:10px;border:1px solid #3d6470;color:#b9f2ff;border-radius:999px;padding:4px 8px}.wrap{max-width:1480px;margin:auto;padding:26px max(14px,3vw) 60px}.hero{display:grid;grid-template-columns:1.2fr .8fr;gap:20px;align-items:end}.eyebrow{font-size:11px;color:var(--aqua);font-weight:900;letter-spacing:.1em}.hero h1{font-size:clamp(38px,7vw,76px);line-height:.93;margin:8px 0;letter-spacing:-.055em}.hero p{color:var(--muted);font-size:16px;max-width:720px}.research{border:1px solid var(--line);border-radius:16px;padding:16px;background:#0a0e10;color:#b8c4c8}.research b{color:#fff}.layout{display:grid;grid-template-columns:minmax(300px,.72fr) minmax(0,1.5fr);gap:16px;margin-top:22px}.panel{background:linear-gradient(180deg,#101416,#0b0e0f);border:1px solid var(--line);border-radius:20px}.mixer{padding:18px;position:sticky;top:72px;align-self:start}.mixer h2,.results h2{margin:0 0 5px}.sub{color:var(--muted);font-size:12px}.group{border-top:1px solid #20282b;padding-top:13px;margin-top:13px}.labelrow{display:flex;justify-content:space-between;gap:12px;align-items:center;margin-bottom:6px}.labelrow b{font-size:12px}.value{color:var(--aqua);font-weight:900;font-size:12px}.range{width:100%;accent-color:#50dcff}.select,.seg button{border:1px solid #313b3e;background:#0a0d0e;color:#dde7ea;border-radius:10px;padding:9px 10px}.select{width:100%}.seg{display:flex;gap:6px;flex-wrap:wrap}.seg button{cursor:pointer;font-size:11px}.seg button.active{border-color:var(--aqua);color:#c8f6ff;background:#0b2026}.timebox{background:#081317;border:1px solid #21434d;border-radius:14px;padding:12px}.timebig{font-size:28px;font-weight:900;letter-spacing:-.04em}.quick{display:flex;gap:6px;flex-wrap:wrap;margin-top:8px}.quick button{border:1px solid #2f4147;background:#0b1417;color:#c5d6db;border-radius:999px;padding:6px 9px;font-size:10px;cursor:pointer}.results{padding:18px}.best{display:grid;grid-template-columns:1.15fr .85fr;gap:12px;margin-top:12px}.winner{border:1px solid #2c5b49;background:linear-gradient(145deg,#0f2a20,#0b1210 60%);border-radius:18px;padding:18px;min-height:230px}.winner .score{font-size:62px;line-height:.9;font-weight:950;color:var(--green);letter-spacing:-.07em}.winner h3{font-size:29px;margin:5px 0}.metrics{display:flex;flex-wrap:wrap;gap:7px;margin-top:12px}.metric{border:1px solid #294139;background:#0b1713;border-radius:999px;padding:6px 9px;font-size:11px}.uvbox{border:1px solid #574522;background:#1b1408;border-radius:16px;padding:14px}.uvnum{font-size:42px;font-weight:950;color:#ffd16e}.uvbox p{color:#d8c49d;margin:6px 0;font-size:12px}.rank{display:grid;gap:8px;margin-top:12px}.rankrow{display:grid;grid-template-columns:42px 1fr auto;gap:10px;align-items:center;border:1px solid var(--line);border-radius:14px;background:#0b0f10;padding:11px}.ranknum{font-size:20px;font-weight:900;color:#7e939a}.rankrow b{display:block}.rankrow small{color:var(--muted)}.rankscore{font-size:20px;font-weight:900}.timeline{margin-top:18px;border-top:1px solid #20282b;padding-top:16px}.timeline-grid{display:grid;grid-template-columns:repeat(7,minmax(100px,1fr));gap:7px;overflow-x:auto;padding-bottom:5px}.slot{border:1px solid var(--line);background:#0a0e0f;border-radius:12px;padding:9px;min-width:105px}.slot.good{border-color:#2f6c50}.slot.fair{border-color:#745a2d}.slot .t{color:#8ea0a5;font-size:10px}.slot b{display:block;font-size:12px;margin:3px 0}.slot .s{font-size:18px;font-weight:900}.explain{margin-top:16px;border:1px solid #263035;background:#080b0c;border-radius:14px;padding:13px;color:#9baaae;font-size:11px}.legend{display:flex;gap:12px;flex-wrap:wrap;margin-top:8px}.dot{width:8px;height:8px;border-radius:50%;display:inline-block}.dot.g{background:var(--green)}.dot.a{background:var(--amber)}.dot.r{background:var(--red)}@media(max-width:900px){.hero,.layout,.best{grid-template-columns:1fr}.mixer{position:static}.timeline-grid{grid-template-columns:repeat(7,130px)}}
</style></head><body><header class="top"><a class="brand" href="/"><b>COSTA</b>CAMS</a><span class="beta">SURF MATCH BETA</span></header><main class="wrap">
<section class="hero"><div><div class="eyebrow">PERSONALISED SURF DECISION ENGINE</div><h1>Where should I surf?</h1><p>Pick when you can surf and what kind of session you want. CostaCams ranks the coast from The Spit to Byron for your ability, board and preferred wave style.</p></div><div class="research"><b>Built from real surf variables.</b><br>Ability, wave size and period materially affect surfing performance. The beta also adapts ideas used by surf parks: recent surf frequency, experience level, maximum wave height and regular board type.</div></section>
<section class="layout"><aside class="panel mixer"><h2>Your surf mixer</h2><div class="sub">Tune the session like a DJ console. Changes recalculate instantly.</div>
<div class="group"><div class="timebox"><div class="labelrow"><b>When can you surf?</b><select class="select" id="day" style="width:auto"><option value="0">Today</option><option value="1">Tomorrow</option></select></div><div class="timebig" id="timeLabel">5:00 PM</div><input class="range" id="time" type="range" min="5" max="19" step="0.5" value="17"><div class="quick"><button data-time="now">Now</button><button data-time="7">Before work</button><button data-time="12">Noon</button><button data-time="17">After work</button><button data-time="18">Sunset-ish</button></div></div></div>
<div class="group"><div class="labelrow"><b>Experience</b></div><select class="select" id="level"><option value="learning">Learning</option><option value="competent" selected>Competent</option><option value="good">Good</option><option value="very_good">Very good</option></select></div>
<div class="group"><div class="labelrow"><b>Surfed in last 2 months</b></div><div class="seg" id="frequency"><button data-v="0">0</button><button data-v="few" class="active">1–4</button><button data-v="many">5+</button></div></div>
<div class="group"><div class="labelrow"><b>Regular board</b></div><select class="select" id="board"><option value="softboard">Softboard</option><option value="longboard">Longboard</option><option value="midlength" selected>Mid-length</option><option value="shortboard">Shortboard</option><option value="bodyboard">Bodyboard</option></select><div class="labelrow" style="margin-top:9px"><b>Board length</b><span class="value" id="boardLenOut">7'0</span></div><input class="range" id="boardLen" type="range" min="5" max="10" step="0.5" value="7"></div>
<div class="group"><div class="labelrow"><b>Wave size you want</b><span class="value" id="waveOut">0.9 m</span></div><input class="range" id="wave" type="range" min="0.3" max="2.5" step="0.1" value="0.9"><div class="labelrow" style="margin-top:9px"><b>Maximum you've surfed</b></div><select class="select" id="maxWave"><option value="0.6">Knee high</option><option value="1.0" selected>Waist high</option><option value="1.5">Chest high</option><option value="2.0">Head high</option><option value="3.0">Overhead +</option></select></div>
<div class="group"><div class="labelrow"><b>Power</b><span class="value" id="powerOut">Medium</span></div><input class="range" id="power" type="range" min="0" max="100" step="5" value="50"></div>
<div class="group"><div class="labelrow"><b>Wave direction</b></div><div class="seg" id="hand"><button data-v="any" class="active">Any</button><button data-v="left">← Left</button><button data-v="right">Right →</button></div></div>
<div class="group"><div class="labelrow"><b>Wind tolerance</b><span class="value" id="windOut">15 km/h</span></div><input class="range" id="wind" type="range" min="5" max="35" step="1" value="15"><div class="labelrow" style="margin-top:9px"><b>Rain tolerance</b></div><div class="seg" id="rain"><button data-v="low" class="active">Prefer dry</button><button data-v="high">Rain is fine</button></div></div>
</aside><section class="panel results"><h2 id="resultTitle">Best match</h2><div class="sub" id="resultSub">Personalised for your selected time.</div><div class="best"><div class="winner" id="winner"></div><div class="uvbox" id="uvbox"></div></div><div class="rank" id="rank"></div><div class="timeline"><h3>Best beach through the day</h3><div class="sub">Same surf profile, different times.</div><div class="timeline-grid" id="timeline"></div></div><div class="explain"><b>Beta scoring:</b> wave-size match, period, estimated wave power, wind speed/direction, rain tolerance, board type, experience and left/right preference. This is a decision aid, not a safety assessment. Local banks, crowds, currents and lifeguard advice can materially change whether a spot is suitable.</div></section></section>
</main><script>
const spots=<?=$dataset?>;
const state={frequency:'few',hand:'any',rain:'low'};
const $=id=>document.getElementById(id);const clamp=(n,a,b)=>Math.max(a,Math.min(b,n));const circ=(a,b)=>{let d=Math.abs((a-b)%360);return d>180?360-d:d};
function setSeg(id,key){document.querySelectorAll('#'+id+' button').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('#'+id+' button').forEach(x=>x.classList.remove('active'));b.classList.add('active');state[key]=b.dataset.v;render();}));}
setSeg('frequency','frequency');setSeg('hand','hand');setSeg('rain','rain');
function fmtTime(v){let h=Math.floor(v),m=Math.round((v-h)*60);if(m===60){h++;m=0;}const ap=h>=12?'PM':'AM',hh=((h+11)%12)+1;return hh+':'+String(m).padStart(2,'0')+' '+ap;}
function profile(){return {level:$('level').value,board:$('board').value,boardLen:+$('boardLen').value,wave:+$('wave').value,maxWave:+$('maxWave').value,power:+$('power').value,wind:+$('wind').value,frequency:state.frequency,hand:state.hand,rain:state.rain};}
function selectedEpoch(hourOverride=null,dayOverride=null){const h=hourOverride??+$('time').value,d=dayOverride??+$('day').value;const now=new Date();const qld=new Date(now.toLocaleString('en-US',{timeZone:'Australia/Brisbane'}));qld.setDate(qld.getDate()+d);qld.setHours(Math.floor(h),Math.round((h%1)*60),0,0);const iso=qld.getFullYear()+'-'+String(qld.getMonth()+1).padStart(2,'0')+'-'+String(qld.getDate()).padStart(2,'0')+'T'+String(qld.getHours()).padStart(2,'0')+':'+String(qld.getMinutes()).padStart(2,'0')+':00+10:00';return new Date(iso).getTime()/1000;}
function nearestHour(s,epoch){if(!s.hours.length)return null;let best=s.hours[0],bd=Math.abs(best.epoch-epoch);for(const h of s.hours){const d=Math.abs(h.epoch-epoch);if(d<bd){best=h;bd=d;}}return bd<=5400?best:null;}
function boardTarget(board,len){if(board==='softboard')return {size:.55,power:25};if(board==='longboard')return {size:.65,power:30};if(board==='midlength')return {size:.85,power:45};if(board==='shortboard')return {size:1.15,power:65};if(board==='bodyboard')return {size:1.05,power:70};return {size:.8,power:45};}
function score(s,h,p){if(!h||h.wave_height==null||h.wave_period==null)return {score:0,why:['forecast unavailable']};const skill={learning:{ideal:.55,max:.9,period:7},competent:{ideal:.8,max:1.4,period:8},good:{ideal:1.05,max:2.0,period:9.5},very_good:{ideal:1.25,max:3.0,period:11}}[p.level];const bt=boardTarget(p.board,p.boardLen);const target=(p.wave*0.55+skill.ideal*.25+bt.size*.20);const sizeScore=clamp(100-Math.abs(h.wave_height-target)*75,0,100);let periodScore=clamp(35+(h.wave_period-5)*13,10,100);if(p.level==='learning'&&h.wave_period>11&&h.wave_height>.8)periodScore-=18;const energy=h.wave_height*h.wave_height*h.wave_period*.49;const targetEnergy=.25+(p.power/100)*5.5;const energyScore=clamp(100-Math.abs(energy-targetEnergy)*23,0,100);const windSpeed=h.wind_speed??20;const speedScore=clamp(100-Math.max(0,windSpeed-p.wind)*6,20,100);const dirDiff=h.wind_direction==null?90:circ(h.wind_direction,s.offshore_from);const dirScore=windSpeed<5?100:clamp(100-dirDiff*.55,10,100);const windScore=.55*speedScore+.45*dirScore;let handScore=100;if(p.hand!=='any'&&s.handedness!=='both'&&s.handedness!==p.hand)handScore=35;const rainProb=h.rain_probability??0;const rainScore=p.rain==='high'?100:clamp(100-rainProb*.75,20,100);let safety=100;const expMax=Math.min(p.maxWave,skill.max);if(h.wave_height>expMax)safety=clamp(100-(h.wave_height-expMax)*110,0,100);if(p.frequency==='0')safety-=10;if(p.frequency==='few')safety-=3;let boardScore=clamp(100-Math.abs(h.wave_height-bt.size)*55,30,100);let total=sizeScore*.24+periodScore*.13+energyScore*.13+windScore*.25+handScore*.08+rainScore*.05+boardScore*.05+safety*.07;total=clamp(Math.round(total),0,100);const why=[];why.push(Math.abs(h.wave_height-target)<.25?'size matches you':(h.wave_height>target?'bigger than your target':'smaller than your target'));why.push(dirScore>70?'favourable wind direction':(windSpeed<7?'light wind':'less favourable wind'));if(h.wave_period>=10)why.push('longer period');if(safety<65)why.push('above your experience range');return {score:total,energy:+energy.toFixed(2),why};}
function allAt(epoch,p){return spots.map(s=>{const h=nearestHour(s,epoch);return {s,h,r:score(s,h,p)}}).filter(x=>x.h).sort((a,b)=>b.r.score-a.r.score);}
function uvAdvice(uv){if(uv<3)return {level:'Low',text:'Minimal protection is generally needed, but use sun protection for long sessions.'};if(uv<6)return {level:'Moderate',text:'Use broad-spectrum water-resistant SPF50+, rashie/UPF clothing and reapply after surfing.'};if(uv<8)return {level:'High',text:'SPF50+ water-resistant, rashie/UPF clothing, sunglasses/hat off-water; reduce unnecessary exposure.'};if(uv<11)return {level:'Very high',text:'Strong protection required. SPF50+, cover up and avoid extra midday exposure when practical.'};return {level:'Extreme',text:'Extreme UV. Strong protection is essential; avoid unnecessary midday exposure when practical.'};}
function metric(v){return '<span class="metric">'+v+'</span>';}
function renderAt(epoch){const p=profile(),rows=allAt(epoch,p),top=rows[0];if(!top){$('winner').innerHTML='<h3>No forecast available</h3>';return;}const h=top.h,s=top.s,r=top.r;$('resultTitle').textContent='Best match · '+fmtTime(+$('time').value);$('resultSub').textContent='Queensland time · '+h.local+' at '+s.name+' local time';$('winner').innerHTML='<div class="score">'+r.score+'</div><div class="sub">PERSONAL MATCH / 100</div><h3>'+s.name+'</h3><div class="sub">'+s.region+' · '+s.break_type+' · '+(s.handedness==='right'?'predominantly right':s.handedness)+'</div><div class="metrics">'+metric('🌊 '+(h.wave_height??'—')+' m · '+(h.wave_period??'—')+' s')+metric('⚡ '+r.energy+' kW/m')+metric('Swell '+(h.swell_compass??'—')+' '+(h.swell_height??'—')+' m')+metric('💨 '+(h.wind_compass??'—')+' '+(h.wind_speed??'—')+' km/h')+metric('🌧 '+Math.round(h.rain_probability??0)+'%')+'</div><p class="sub" style="margin-top:12px">'+r.why.join(' · ')+'</p>';
const ua=uvAdvice(h.uv??0);$('uvbox').innerHTML='<div class="sub">FORECAST UV AT THIS TIME</div><div class="uvnum">UV '+(h.uv??0).toFixed(1)+'</div><b>'+ua.level+'</b><p>'+ua.text+'</p><div class="sub">Daily max '+(h.uv_max??0).toFixed(1)+' · estimated from forecast max and daylight curve in this beta.</div>';
$('rank').innerHTML=rows.slice(1,4).map((x,i)=>'<div class="rankrow"><div class="ranknum">#'+(i+2)+'</div><div><b>'+x.s.name+'</b><small>'+x.h.wave_height+' m · '+x.h.wave_period+' s · '+x.h.wind_compass+' '+x.h.wind_speed+' km/h · UV '+x.h.uv.toFixed(1)+'</small></div><div class="rankscore">'+x.r.score+'</div></div>').join('');}
function renderTimeline(){const p=profile(),day=+$('day').value,hours=[6,8,10,12,14,16,18];$('timeline').innerHTML=hours.map(hr=>{const rows=allAt(selectedEpoch(hr,day),p),x=rows[0];if(!x)return '';const cls=x.r.score>=75?'good':(x.r.score>=55?'fair':'');return '<div class="slot '+cls+'"><div class="t">'+fmtTime(hr)+'</div><b>'+x.s.name+'</b><div class="s">'+x.r.score+'</div><small>'+x.h.wave_height+'m · '+x.h.wave_period+'s · UV '+x.h.uv.toFixed(1)+'</small></div>';}).join('');}
function render(){const t=+$('time').value;$('timeLabel').textContent=fmtTime(t);$('boardLenOut').textContent=(+$('boardLen').value).toFixed(1).replace('.0','')+"'";$('waveOut').textContent=(+$('wave').value).toFixed(1)+' m';const pv=+$('power').value;$('powerOut').textContent=pv<35?'Soft':(pv>65?'Powerful':'Medium');$('windOut').textContent=$('wind').value+' km/h';renderAt(selectedEpoch());renderTimeline();}
['day','time','level','board','boardLen','wave','maxWave','power','wind'].forEach(id=>$(id).addEventListener('input',render));document.querySelectorAll('[data-time]').forEach(b=>b.addEventListener('click',()=>{let v=b.dataset.time;if(v==='now'){const q=new Date(new Date().toLocaleString('en-US',{timeZone:'Australia/Brisbane'}));v=q.getHours()+q.getMinutes()/60;}$('time').value=clamp(+v,5,19);render();}));render();
</script></body></html>